(window.EXSUB_C=window.EXSUB_C||{})[11]={"a-96":[{"t":"Tramitación simplificada del procedimiento administrativo común (art. 96 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Tramitación simplificada del procedimiento administrativo común (art. 96 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Motivos</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Razones de interés público.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Falta de complejidad.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">En cualquier momento antes de la resolución, el <mark class=\"m-autoridad\">órgano</mark> competente para su tramitación <mark class=\"m-plazo\">puede acordar continuar con tramitación ordinaria</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Las Administraciones públicas <mark class=\"m-accion\">podrán acordar</mark> la tramitación simplificada</div><div class=\"vt-hijos\"><div class=\"vt-nodo\"><div class=\"vt-et v\">De oficio</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Deberá notificarlo</mark> al interesado.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Si algún interesado manifiesta su <u class=\"m-clave\">oposición expresa</u>, la Administración <mark class=\"m-accion\">continuará</mark> con la tramitación ordinaria.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">A solicitud del interesado</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">5 días</span><div class=\"vt-t\">Si no se aprecian las razones previas: desestimación no recurrible, en el plazo de 5 días.</div></div></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Plazo máximo de duración</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">30 días</span><div class=\"vt-t\">desde el siguiente a la notificación del acuerdo. <u class=\"m-clave\">Salvo</u> que reste menos para su tramitación ordinaria.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Trámites únicos</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">a) Inicio. b) Subsanación de la solicitud, en su caso. c) Alegaciones al inicio (5 días). d) <mark class=\"m-autoridad\">Audiencia</mark> (si la resolución es desfavorable). e) Informe del servicio jurídico (si es preceptivo). f) Informe del <mark class=\"m-autoridad\">Consejo</mark> General del Poder Judicial (si es preceptivo).</div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">g) Dictamen del <mark class=\"m-autoridad\">Consejo de Estado u órgano</mark> consultivo equivalente de la Comunidad Autónoma (si es preceptivo)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Desde que se solicite el Dictamen hasta que éste sea emitido: <mark class=\"m-plazo\">suspensión automática del plazo para resolver</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">15 días</span><div class=\"vt-t\">El <mark class=\"m-autoridad\">órgano</mark> competente <mark class=\"m-accion\">solicitará</mark> la emisión del Dictamen en un plazo tal que permita cumplir el plazo de resolución del procedimiento. El Dictamen <mark class=\"m-accion\">podrá</mark> ser emitido en el plazo de 15 días si así lo solicita el <mark class=\"m-autoridad\">órgano</mark> competente.</div></div></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">h) Resolución.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Si se realizan más trámites de los expuestos, el procedimiento <u class=\"m-clave\">debe</u> ser tramitado de manera <mark class=\"m-plazo\">ordinaria</mark>.</div></div></div></div></div></div>"}],"a-125":[{"t":"Plazos de los recursos administrativos (cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Plazos de los recursos administrativos (cuadro del temario)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Recurso de ALZADA</h5><ul><li>Interposición: <mark class=\"m-plazo\">1 mes</mark> (expreso)</li><li>Resolución: <mark class=\"m-plazo\">3 meses</mark></li></ul></div><div class=\"vis-col\"><h5>Potestativo de REPOSICIÓN</h5><ul><li>Interposición: <mark class=\"m-plazo\">1 mes</mark> (expreso)</li><li>Resolución: <mark class=\"m-plazo\">1 mes</mark></li></ul></div><div class=\"vis-col\"><h5>Extraordinario de REVISIÓN</h5><ul><li>Interposición: <mark class=\"m-plazo\">4 años</mark> (si es por 125.1.a, error de hecho) · <mark class=\"m-plazo\">3 meses</mark> para el resto de casos</li><li>Resolución: <mark class=\"m-plazo\">3 meses</mark></li></ul></div></div></div>"},{"t":"Plazos de 3, 5 y 7 días (Ley 39/2015 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos de 3, 5 y 7 días (Ley 39/2015 · cuadro del temario)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">3 días</span>Segundo intento de notificación en papel. <b>Art. 42.2</b></div><div class=\"vis-plazo\"><span class=\"n\">5 días</span>Ampliación del plazo de subsanación por no reunir los requisitos en la presentación de la solicitud (cuando los documentos requeridos presenten dificultades especiales). <b>Art. 68.2</b></div><div class=\"vis-plazo\"><span class=\"n\">5 días</span>Desestimación por parte del <mark class=\"m-autoridad\">órgano</mark> competente de la tramitación simplificada del procedimiento. <b>Art. 96.3</b></div><div class=\"vis-plazo\"><span class=\"n\">7 días</span>Alegaciones tras realización de actuaciones complementarias. <b>Art. 87</b></div><div class=\"vis-plazo\"><span class=\"n\">5 días</span>Procedimiento: alegaciones dentro de la tramitación simplificada. <b>Art. 96.6</b></div></div></div>"},{"t":"Plazos de 10 días (Ley 39/2015 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos de 10 días (Ley 39/2015 · cuadro del temario)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Subsanación de la representación. <b>Art. 5.6</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Informe vinculante de la <mark class=\"m-autoridad\">secretaría</mark> de estado de seguridad (sistemas de identificación y firma). <b>Art. 9.2.c y 10.2.c</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Comunicación del plazo máximo de resolución del procedimiento y notificación de actos. <b>Art. 21.4</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Remisión de informes preceptivos ya elaborados por un <mark class=\"m-autoridad\">órgano</mark> administrativo distinto al que tramita el procedimiento. <b>Art. 28</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Notificación de actos y resoluciones desde que se dictan. <b>Art. 40.2</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Rechazo de la notificación electrónica porque no se ha accedido a su contenido (días naturales). <b>Art. 43.2</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Plazo para aportar alegaciones en un procedimiento de responsabilidad patrimonial de oficio. <b>Art. 65.2</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Subsanación de la solicitud de iniciación de un procedimiento por parte de interesado. <b>Art. 68.1</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Cumplimentación de trámites por parte de los interesados (salvo que la norma fije uno distinto). <b>Art. 73.1 y 73.2</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Remisión de informes. <b>Art. 80.2 y 81.1</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Remisión de propuesta en responsabilidad patrimonial. <b>Art. 81.2</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Instar la continuación del procedimiento por terceros interesados tras desistimiento o renuncia. <b>Art. 94.4</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Si el recurso de alzada se ha presentado ante el <mark class=\"m-autoridad\">órgano</mark> que dictó el acto impugnado, este debe trasladarlo al competente (superior jerárquico) en el plazo de 10 días. <b>Art. 121.2</b></div></div></div>"},{"t":"Plazos de 15 días (Ley 39/2015 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos de 15 días (Ley 39/2015 · cuadro del temario)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Expedición de la certificación del silencio administrativo. <b>Art. 24.4</b></div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Solicitud por parte del interesado a la administración de la expedición de copias auténticas de documentos válidamente emitidos. <b>Art. 27.4</b></div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Confirmación / modificación / levantamiento de medidas provisionales en caso de urgencia inaplazable. <b>Art. 82.2</b></div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Plazo máximo de realización de las actuaciones complementarias. <b>Art. 87</b></div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Plazo para formular alegaciones y aportar pruebas por cuestiones conexas que no han sido tenidas en cuenta por los interesados. <b>Art. 88</b></div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Alegaciones por considerar la infracción o sanción de mayor gravedad que la determinada en la propuesta de resolución (procedimiento de carácter sancionador). <b>Art. 90.2</b></div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Emisión de dictámenes en la tramitación simplificada. <b>Art. 96.6</b></div></div></div>"},{"t":"Plazos de 20 días, 30 días, 1 mes, 2 meses y 3 meses (Ley 39/2015 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos de 20 días, 30 días, 1 mes, 2 meses y 3 meses (Ley 39/2015 · cuadro del temario)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">20 días</span>Plazo mínimo de alegación tras la apertura de un período de información pública. <b>Art. 83.2</b></div><div class=\"vis-plazo\"><span class=\"n\">30 días</span>Salvo que reste menos para su tramitación ordinaria, la resolución de la tramitación simplificada del procedimiento <mark class=\"m-accion\">deberá</mark> ser resuelta en 30 días. <b>Art. 96.6</b></div><div class=\"vis-plazo\"><span class=\"n\">1 mes</span>La ejecución de la suspensión de un acto impugnado se considera suspendida si transcurrido un mes desde la solicitud de suspensión la administración no se pronuncia (se entiende que el silencio es positivo). <b>Art. 117.3</b></div><div class=\"vis-plazo\"><span class=\"n\">2 meses</span>Impugnar vía jurisdiccional sistemas de identificación y de firma. <b>Art. 9.2.c y 10.2.c</b></div><div class=\"vis-plazo\"><span class=\"n\">2 meses</span>Dictamen preceptivo del <mark class=\"m-autoridad\">Consejo de Estado</mark> en procedimiento de responsabilidad patrimonial por igual o superior a 50.000 euros. <b>Art. 81.2</b></div><div class=\"vis-plazo\"><span class=\"n\">2 meses</span>Informe preceptivo del <mark class=\"m-autoridad\">Consejo</mark> General del Poder Judicial en procedimiento de responsabilidad patrimonial por un funcionamiento anormal de la administración de justicia. <b>Art. 81.3</b></div><div class=\"vis-plazo\"><span class=\"n\">3 meses</span>Plazo máximo de resolución si no se fija plazo en la norma. <b>Art. 21.3</b></div><div class=\"vis-plazo\"><span class=\"n\">3 meses</span>La suspensión máxima de un procedimiento por petición de informes preceptivos. <b>Art. 22.1</b></div><div class=\"vis-plazo\"><span class=\"n\">3 meses</span>Caducidad de los procedimientos iniciados a solicitud de interesado. <b>Art. 95.1</b></div></div></div>"},{"t":"Plazos de 6 meses y de 1, 4 y 5 años (Ley 39/2015 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos de 6 meses y de 1, 4 y 5 años (Ley 39/2015 · cuadro del temario)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">6 meses</span>Plazo máximo de resolución fijado en la norma. <b>Art. 21.2</b></div><div class=\"vis-plazo\"><span class=\"n\">6 meses</span>Si en un procedimiento de responsabilidad patrimonial la administración no se pronuncia de forma expresa en el plazo de 6 meses desde que se inició el procedimiento, se considera contraria a la indemnización (silencio negativo). <b>Art. 91.3</b></div><div class=\"vis-plazo\"><span class=\"n\">6 meses</span>Procedimiento de revisión iniciado de oficio: el transcurso del plazo de 6 meses sin resolución expresa por parte de la administración produce caducidad. <b>Art. 106.5</b></div><div class=\"vis-plazo\"><span class=\"n\">6 meses</span>Desestimación en la revisión de actos nulos iniciados a solicitud de interesado. <b>Art. 106.5</b></div><div class=\"vis-plazo\"><span class=\"n\">6 meses</span>Transcurso del plazo de 6 meses sin que la administración declare la lesividad: produce la caducidad del procedimiento. <b>Art. 107.3</b></div><div class=\"vis-plazo\"><span class=\"n\">1 año</span>Prescripción del derecho de reclamación en un procedimiento de responsabilidad patrimonial. <b>Art. 67.1</b></div><div class=\"vis-plazo\"><span class=\"n\">4 años</span>Límite en la aplicación de la declaración de lesividad. <b>Art. 107.2</b></div><div class=\"vis-plazo\"><span class=\"n\">5 años</span>Límite máximo del poder de representación (renovable por otros 5 años de forma indefinida). <b>Art. 6.6</b></div><div class=\"vis-plazo\"><span class=\"n\">10-30 días</span>Período de prueba de (10-30 días) + un extraordinario de (1-10 días). <b>Art. 77.2</b></div><div class=\"vis-plazo\"><span class=\"n\">10-15 días</span>Trámite de <mark class=\"m-autoridad\">audiencia</mark> (10-15 días). <b>Art. 82</b></div><div class=\"vis-plazo\"><span class=\"n\">10-15 días</span>Plazo (10-15 días) para tener en cuenta hechos nuevos o documentos no recogidos en el expediente originario (recurso). <b>Art. 118.1</b></div></div></div>"}],"a-133":[{"t":"Plazos de la Ley 50/1997, del Gobierno (cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos de la Ley 50/1997, del Gobierno (cuadro del temario)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">2 enero o 1 julio</span>Las disposiciones de entrada en vigor de leyes o reglamentos cuya aprobación o propuesta corresponda al <mark class=\"m-autoridad\">Gobierno</mark> y que impongan obligaciones, <mark class=\"m-accion\">preverán</mark> el comienzo de su vigencia el 2 de enero o 1 de julio siguientes a su aprobación. <b>Art. 23</b></div><div class=\"vis-plazo\"><span class=\"n\">15 días o 7 días</span>Plazo mínimo de <mark class=\"m-autoridad\">audiencia</mark> e información pública en el proceso de elaboración de normas, cuando la norma afecte a derechos e intereses legítimos, <mark class=\"m-accion\">será</mark> de 15 días hábiles, pudiendo ser reducido a 7 días hábiles. <b>Art. 26.6</b></div><div class=\"vis-plazo\"><span class=\"n\">7 días</span>Trámite de <mark class=\"m-autoridad\">audiencia</mark> pública e información pública del 26.6 en la tramitación de urgencia de iniciativas normativas en el ámbito AGE, <mark class=\"m-accion\">será</mark> de 7 días. <b>Art. 27.2.b</b></div><div class=\"vis-plazo\"><span class=\"n\">10 días o 1 mes</span>Emisión de informes preceptivos para el procedimiento de elaboración de normas: plazo de 10 días, o 1 mes si se solicita a una administración dotada de especial independencia o autonomía. <b>Art. 26.5</b></div><div class=\"vis-plazo\"><span class=\"n\">+15 días naturales</span>En los procedimientos de elaboración de normas, el tiempo de consulta mínimo establecido para emitir una opinión nunca <mark class=\"m-accion\">será</mark> inferior a 15 días naturales. <b>Art. 26.1</b></div><div class=\"vis-plazo\"><span class=\"n\">Antes 30 abril</span>El <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-accion\">aprobará</mark> anualmente un plan normativo, elevado por el ministro de la <mark class=\"m-autoridad\">Presidencia</mark> al <mark class=\"m-autoridad\">Consejo de Ministros</mark> para su aprobación antes del 30 de abril. <b>Art. 25</b></div></div></div>"}],"a-24":[{"t":"Silencio administrativo: qué efectos tiene (art. 24 Ley 39/2015)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Silencio administrativo: qué efectos tiene (art. 24 Ley 39/2015)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">24</span>Si la Administración no resuelve y notifica en plazo (<mark class=\"m-plazo\">el fijado por la norma reguladora; máximo seis meses</mark>, salvo ley o Derecho de la UE), actúa el <mark class=\"m-destacable\">silencio administrativo</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso si\"><span class=\"et\">Estimatorio</span>La estimación por silencio tiene a todos los efectos <mark class=\"m-resp\">la consideración de acto administrativo finalizador del procedimiento</mark></div><div class=\"vis-paso no\"><span class=\"et\">Desestimatorio</span>La desestimación por silencio tiene los solos efectos de <mark class=\"m-resp\">permitir a los interesados la interposición del recurso administrativo o contencioso-administrativo que resulte procedente</mark></div></div></div></div>"}],"r-13":[{"t":"Órganos de prevención de riesgos laborales en la Guardia Civil (arts. 13 a 15 RD 179/2005)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Órganos de prevención de riesgos laborales en la Guardia Civil (arts. 13 a 15 RD 179/2005)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Órganos</mark> <mark class=\"m-destacable\">de prevención</mark> en la Dirección General de la Guardia Civil (art. 13.2)</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) Servicio de Prevención</div><div class=\"vis-rama\">b) Sección de Prevención de Zona</div><div class=\"vis-rama\">c) <mark class=\"m-autoridad\">Oficina</mark> de Prevención de Comandancia</div><div class=\"vis-rama\">d) Otras unidades</div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Órgano</mark> de asesoramiento (art. 14):<div class=\"vis-sub\"><span>el <mark class=\"m-autoridad\">Consejo</mark> de la Guardia Civil analiza y valora las propuestas del principio de participación (art. 8)</span></div></div><div class=\"vis-rama\">Inspección y control (art. 15):<div class=\"vis-sub\"><span>interno: cada <mark class=\"m-autoridad\">órgano</mark> de prevención controla a los <mark class=\"m-autoridad\">órganos</mark> que de él dependen</span><span>externo: la Inspección de Personal y Servicios de Seguridad de la <mark class=\"m-autoridad\">Secretaría de Estado</mark> de Seguridad (el Servicio de Prevención le remite copia de la memoria anual)</span></div></div></div></div></div>"}],"a-1":[{"t":"Objeto de la Ley 39/2015 (art. 1 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Objeto de la Ley 39/2015 (art. 1 · cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">Regula</span><mark class=\"m-destacable\">El procedimiento administrativo común</mark> a todas las Administraciones Públicas (incluyendo el sancionador y el de reclamación de responsabilidad) · <mark class=\"m-destacable\">los requisitos de validez y eficacia</mark> de los actos administrativos · <mark class=\"m-destacable\">los principios</mark> de la iniciativa legislativa y de la potestad reglamentaria</div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso si\"><span class=\"et\">Mediante LEY</span>Cuando resulte <mark class=\"m-plazo\">eficaz, proporcionado, necesario y motivado</mark>: <mark class=\"m-accion\">podrán incluirse</mark> <mark class=\"m-resp\">trámites adicionales o distintos</mark> a los de esta Ley</div><div class=\"vis-paso no\"><span class=\"et\">Mediante REGLAMENTO</span><mark class=\"m-accion\">Podrán establecerse</mark> <mark class=\"m-resp\">especialidades</mark> referidas a: <mark class=\"m-autoridad\">órganos</mark> competentes · plazos propios por razón de la materia · formas de iniciación y terminación · publicación e informes a recabar</div></div></div></div>"}],"a-5":[{"t":"Representación en el procedimiento administrativo (art. 5 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Representación en el procedimiento administrativo (art. 5 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Actuación</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por medio de representante: <mark class=\"m-destacable\">interesados con capacidad de obrar</mark>.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">En representación de otras personas: personas físicas con capacidad de obrar y personas jurídicas <u class=\"m-clave\">siempre que</u> ello esté previsto en sus Estatutos.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Acreditación</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Debe acreditarse la representación para: formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir de acciones y renunciar a derechos. Para los actos y gestiones de mero trámite <mark class=\"m-plazo\">se</mark> <mark class=\"m-accion\">presumirá</mark> la representación.</div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Apoderamiento APUD ACTA (se entiende acreditada mediante)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Comparecencia personal.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Comparecencia electrónica en la correspondiente sede electrónica.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Inscripción en el registro electrónico de apoderamientos de la Administración competente.</div></div></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Falta o insuficiente acreditación</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><u class=\"m-clave\">No impide</u> que se tenga por realizado el acto de que se trate, <u class=\"m-clave\">siempre que</u> se aporte la acreditación o se subsane el defecto.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">10 días</span><div class=\"vt-t\">Plazo para subsanar que debe conceder el <mark class=\"m-autoridad\">órgano</mark> administrativo (o un plazo superior cuando las circunstancias del caso así lo requieran). Art. 5.6</div></div></div></div></div></div>"}],"d-15":[{"t":"Lengua de los procedimientos (art. 15 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Lengua de los procedimientos (art. 15 · cuadro del temario)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Administración General del <mark class=\"m-autoridad\">Estado</mark></h5><ul><li>Lengua: <mark class=\"m-destacable\">CASTELLANO</mark>.</li><li>No obstante, los interesados que se dirijan a <mark class=\"m-autoridad\">órganos</mark> de la AGE <mark class=\"m-plazo\">con sede en el territorio de una Comunidad Autónoma</mark> <mark class=\"m-accion\">podrán utilizar</mark> también la <mark class=\"m-destacable\">lengua cooficial</mark> de esa Comunidad: el procedimiento se tramita en la lengua elegida por el interesado.</li><li>Varios interesados y discrepancia: se tramita en <mark class=\"m-destacable\">castellano</mark>; los documentos o testimonios que requieran los interesados <mark class=\"m-accion\">se expedirán</mark> en la lengua elegida por ellos.</li></ul></div><div class=\"vis-col\"><h5>Administraciones de las CCAA y Entidades Locales</h5><ul><li>Se ajusta a <mark class=\"m-destacable\">lo previsto en la legislación autonómica</mark> correspondiente.</li><li>La Administración instructora <mark class=\"m-accion\">deberá</mark> <mark class=\"m-resp\">traducir al castellano</mark> los documentos que: deban surtir efecto fuera del territorio de la Comunidad, estén dirigidos a interesados que lo soliciten, o deban surtir efectos en el territorio de otra Comunidad con lengua cooficial distinta.</li><li>En ese último caso <u class=\"m-clave\">no</u> <mark class=\"m-accion\">será</mark> <u class=\"m-clave\">precisa</u> su traducción.</li></ul></div></div></div>"}],"a-22":[{"t":"Plazo máximo para resolver y notificar (art. 21 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Plazo máximo para resolver y notificar (art. 21 · cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">Art. 21</span>El plazo máximo para notificar resolución expresa es el fijado por la <mark class=\"m-destacable\">norma reguladora</mark> del procedimiento</div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso no\"><span class=\"et\">Si la norma no fija plazo</span>El plazo es de <mark class=\"m-plazo\">3 meses</mark></div><div class=\"vis-paso si\"><span class=\"et\">Tope</span>El plazo <u class=\"m-clave\">no</u> <mark class=\"m-accion\">podrá</mark> <u class=\"m-clave\">exceder</u> de <mark class=\"m-plazo\">6 meses</mark>, <u class=\"m-clave\">salvo</u> norma con rango de ley o Derecho de la Unión Europea</div></div></div></div>"}],"a-30":[{"t":"Cómputo de plazos (art. 30 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Cómputo de plazos (art. 30 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Plazo señalado</span><span>Cómo se cuenta</span></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Por HORAS <u class=\"m-clave\">(salvo</u> que ley o Derecho de la UE dispongan otro cómputo)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Se entiende que son <mark class=\"m-plazo\">hábiles</mark>: todas las horas del día que formen parte de un día hábil.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Se cuentan de <mark class=\"m-plazo\">hora en hora</mark> y de <mark class=\"m-plazo\">minuto en minuto</mark>, desde la hora y minuto en que tenga lugar la notificación o publicación del acto.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">24 horas</span><div class=\"vt-t\"><u class=\"m-clave\">No</u> <mark class=\"m-accion\">podrán tener</mark> una duración superior a veinticuatro horas, en cuyo caso <mark class=\"m-accion\">se expresarán</mark> en días.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Por DÍAS <u class=\"m-clave\">(salvo</u> que ley o Derecho de la UE dispongan otro cómputo)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Se entiende que son <mark class=\"m-plazo\">hábiles</mark>. Se <u class=\"m-clave\">excluyen</u> los sábados, los domingos y los declarados festivos.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Cuando se señalen por <mark class=\"m-destacable\">días naturales</mark> por ley o Derecho de la UE, <mark class=\"m-accion\">se hará constar</mark> esta circunstancia en las notificaciones.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Se cuentan a partir del <mark class=\"m-plazo\">día siguiente</mark> a la notificación o publicación, o desde el siguiente a aquel en que se produzca la estimación o desestimación por silencio administrativo.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Por MESES o AÑOS</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Se computan a partir del día siguiente a la notificación o publicación (o al de la estimación/desestimación por silencio).</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">El plazo concluye el <mark class=\"m-plazo\">mismo día</mark> en el mes o año de vencimiento. <u class=\"m-clave\">Si no</u> hubiera día equivalente, expira el <mark class=\"m-plazo\">último día del mes</mark>.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Cuando el último día sea <mark class=\"m-destacable\">inhábil</mark>, se entiende prorrogado al primer día hábil siguiente.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Día hábil en el municipio o CA del interesado e inhábil en la sede del <mark class=\"m-autoridad\">órgano</mark> administrativo (o a la inversa): <mark class=\"m-accion\">se considerará</mark> <mark class=\"m-destacable\">inhábil en todo caso</mark>.</div></div></div></div></div></div>"}],"d-33":[{"t":"Tramitación de urgencia (art. 33 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Tramitación de urgencia (art. 33 · cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">33.1</span>Cuando razones de <mark class=\"m-destacable\">interés público</mark> lo aconsejen, <mark class=\"m-accion\">se podrá acordar</mark> <mark class=\"m-resp\">de oficio o a petición del interesado</mark> la tramitación de urgencia</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Efecto</span>Se <mark class=\"m-resp\">reducirán a la mitad</mark> los plazos establecidos para el procedimiento ordinario, <u class=\"m-clave\">salvo</u> los relativos a la presentación de <mark class=\"m-destacable\">solicitudes</mark> y <mark class=\"m-destacable\">recursos</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso no\"><span class=\"et\">33.2</span><u class=\"m-clave\">No</u> <mark class=\"m-accion\">cabrá</mark> <u class=\"m-clave\">recurso alguno</u> contra el acuerdo que declare la aplicación de la tramitación de urgencia, sin perjuicio del procedente contra la resolución que ponga fin al procedimiento</div></div></div>"}],"a-40":[{"t":"Notificación (art. 40 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Notificación (art. 40 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Competencia</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">El <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-destacable\">que dicte</mark> las resoluciones y actos administrativos los <mark class=\"m-accion\">notificará</mark> a los interesados cuyos derechos e intereses sean afectados por aquellos.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Plazo</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">10 días</span><div class=\"vt-t\">a partir de la fecha en que el acto haya sido dictado.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Contenido (DEBE contener)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Texto íntegro</mark> de la resolución, indicando si pone fin o no a la vía administrativa.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Recursos que procedan</mark>, en su caso: en vía administrativa o judicial, <mark class=\"m-autoridad\">órgano</mark> ante el que hubieran de presentarse y plazos para interponerlos.</div></div></div></div></div></div>"}],"a-45":[{"t":"Publicación (art. 45 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Publicación (art. 45 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Cuándo</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Lo establezcan las normas reguladoras de cada procedimiento.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Lo aconsejen razones de <mark class=\"m-destacable\">interés público</mark> apreciadas por el <mark class=\"m-autoridad\">órgano</mark> competente.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Objeto (surte los efectos de la notificación cuando)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">El acto tenga por destinatario una pluralidad indeterminada de personas.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">La Administración estime que la notificación a un solo interesado es insuficiente para garantizar la notificación a todos.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Se trate de actos integrantes de un <mark class=\"m-destacable\">procedimiento selectivo o de concurrencia competitiva</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Contenido</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Texto íntegro de la resolución (indicando si pone fin o no a la vía administrativa) y recursos que procedan.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Lugar</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">En el <mark class=\"m-destacable\">diario oficial</mark> que corresponda según cuál sea la Administración de la que proceda el acto a notificar.</div></div></div></div></div></div>"}],"a-47":[{"t":"Nulidad y anulabilidad (arts. 47 y 48 · «MUY IMPORTANTE» en el temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Nulidad y anulabilidad (arts. 47 y 48 · «MUY IMPORTANTE» en el temario)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>NULIDAD DE PLENO DERECHO (actos)</h5><ul><li><mark class=\"m-accion\">Serán</mark> <mark class=\"m-destacable\">NULOS DE PLENO DERECHO</mark> los siguientes <mark class=\"m-destacable\"><u class=\"m-clave\">ACTOS</u></mark> de las <mark class=\"m-autoridad\">Administraciones Públicas</mark>:</li><li><mark class=\"m-destacable\"><u class=\"m-clave\">Lesionen derechos y libertades</u></mark> <mark class=\"m-personalizado\">susceptibles de amparo constitucional</mark>.</li><li>Dictados por <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-resp\">manifiestamente incompetente</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">por razón</u></mark><span class=\"m-ast\"></span> <u class=\"m-clave\">de la materia o del territorio</u>.</li><li>Tengan un <mark class=\"m-destacable\">contenido imposible</mark>.</li><li>Sean constitutivos de <mark class=\"m-destacable\">infracción penal</mark> o se dicten como consecuencia de ésta.</li><li><mark class=\"m-destacable\">Dictados prescindiendo</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\"><u class=\"m-clave\">total y absolutamente</u></mark></span> del procedimiento <mark class=\"m-personalizado\">legalmente establecido</mark> o de las normas que contienen las <span class=\"m-caja\">reglas esenciales</span> para la <mark class=\"m-personalizado\">formación</mark> de la voluntad de los <mark class=\"m-autoridad\"><u class=\"m-clave\">órganos</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">colegiados</u></mark>.</li><li>Actos expresos o presuntos contrarios al ordenamiento jurídico por los que se <mark class=\"m-destacable\">adquieren facultades o derechos</mark> <span class=\"m-circulo\">cuando</span> <mark class=\"m-personalizado\"><u class=\"m-clave\">se carezca de los requisitos esenciales</u></mark> para su adquisición.</li><li>Cualquier otro que <mark class=\"m-personalizado\">se establezca</mark> <span class=\"m-caja\">expresamente</span> en una <mark class=\"m-destacable\">disposición</mark> con <span class=\"m-circulo\">rango de ley</span>.</li></ul></div><div class=\"vis-col\"><h5>NULIDAD DE PLENO DERECHO (disposiciones)</h5><ul><li><mark class=\"m-accion\">Serán</mark> <mark class=\"m-destacable\">NULAS DE PLENO DERECHO</mark> las <mark class=\"m-destacable\"><u class=\"m-clave\">DISPOSICIONES ADMINISTRATIVAS</u></mark> que:</li><li><mark class=\"m-autoridad\"><u class=\"m-clave\">Vulneren</u></mark>: la <mark class=\"m-personalizado\">Constitución</mark>, las <mark class=\"m-personalizado\">leyes</mark> u <mark class=\"m-destacable\">otras disposiciones administrativas</mark> de <span class=\"m-caja\">rango superior</span>.</li><li>Las que regulen <mark class=\"m-personalizado\">materias reservadas</mark> a la Ley.</li><li>Las que establezcan la <mark class=\"m-destacable\">retroactividad de disposiciones sancionadoras</mark> <span class=\"m-circulo\">no</span> favorables <span class=\"m-circulo\">o</span> <mark class=\"m-destacable\">restrictivas de derechos individuales</mark>.</li></ul></div><div class=\"vis-col\"><h5>ANULABILIDAD</h5><ul><li>Son <mark class=\"m-destacable\">ANULABLES</mark>: los <mark class=\"m-destacable\">actos</mark> de la Administración <mark class=\"m-personalizado\">que incurran en cualquier infracción del ordenamiento jurídico</mark>, <span class=\"m-circulo\">incluso</span> <span class=\"m-flecha\"></span><mark class=\"m-resp\">la desviación de poder</mark>.</li><li><mark class=\"m-personalizado\">No obstante</mark>, el <mark class=\"m-destacable\">defecto de forma</mark> <span class=\"m-circulo\">solo</span> <mark class=\"m-accion\">determinará</mark> la <mark class=\"m-personalizado\">anulabilidad</mark> <span class=\"m-caja\">cuando</span> el <span class=\"m-circulo\">acto</span> carezca de los <mark class=\"m-personalizado\">requisitos formales indispensables</mark> para alcanzar su fin o dé lugar a <mark class=\"m-personalizado\">indefensión de los interesados</mark>.</li><li>La realización de <mark class=\"m-autoridad\">actuaciones administrativas fuera del tiempo</mark> establecido para ellas <mark class=\"m-accion\">implicará</mark> la <mark class=\"m-destacable\">anulabilidad</mark> del acto <span class=\"m-caja\">cuando así lo</span> <mark class=\"m-personalizado\">imponga la naturaleza del término o plazo</mark>.</li></ul></div></div></div>"}],"a-52":[{"t":"Subsanación de actos viciados: conversión, conservación y convalidación (arts. 50-52 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Subsanación de actos viciados: conversión, conservación y convalidación (arts. 50-52 · cuadro del temario)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Conversión (art. 50)</h5><ul><li>Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto <mark class=\"m-accion\">producirán</mark> los efectos de éste.</li></ul></div><div class=\"vis-col\"><h5>Conservación (art. 51)</h5><ul><li>El <mark class=\"m-autoridad\">órgano</mark> que declare la nulidad o anule actuaciones <mark class=\"m-accion\">dispondrá</mark> siempre la <mark class=\"m-destacable\">conservación</mark> de actos y trámites cuyo contenido se hubiera mantenido igual de no haberse cometido la infracción.</li></ul></div><div class=\"vis-col\"><h5>Convalidación (art. 52)</h5><ul><li>La Administración <mark class=\"m-accion\">podrá convalidar</mark> los actos anulables, subsanando los vicios de que adolezcan.</li><li>El acto de convalidación <mark class=\"m-accion\">producirá</mark> efectos desde su fecha, <u class=\"m-clave\">salvo</u> retroactividad cuando proceda (art. 39.3).</li></ul></div></div></div>"}],"a-64":[{"t":"Acuerdo de iniciación en los procedimientos sancionadores (art. 64 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Acuerdo de iniciación en los procedimientos sancionadores (art. 64 · cuadro del temario)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Acuerdo de iniciación</mark> del procedimiento sancionador</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-accion\">Se COMUNICARÁ</mark> al instructor y, cuando las normas así lo prevean, al denunciante<div class=\"vis-sub\"><span>Instructor del procedimiento, trasladándole cuantas actuaciones existan</span><span>Denunciante (cuando las normas reguladoras así lo prevean)</span></div></div><div class=\"vis-rama\"><mark class=\"m-accion\">Se NOTIFICARÁ</mark> a los interesados (en todo caso, al inculpado)<div class=\"vis-sub\"></div></div><div class=\"vis-rama\"><mark class=\"m-accion\">Deberá contener</mark>, al menos:<div class=\"vis-sub\"><span>Identificación de la persona o personas presuntamente responsables</span><span>Hechos que motivan la incoación, su posible calificación y sanciones</span><span>Identificación del instructor y, en su caso, <mark class=\"m-autoridad\">Secretario</mark></span><span><mark class=\"m-autoridad\">Órgano</mark> competente para la resolución y norma que le atribuya la competencia</span><span>Medidas de carácter provisional acordadas</span><span>Indicación del derecho a formular alegaciones y a la <mark class=\"m-autoridad\">audiencia,</mark> y de los plazos</span><span>Si no hay alegaciones en plazo, el acuerdo <mark class=\"m-accion\">podrá considerarse</mark> propuesta de resolución cuando contenga un pronunciamiento preciso sobre la responsabilidad imputada</span></div></div><div class=\"vis-rama\">Excepcionalmente: si no hay elementos suficientes para la calificación inicial, <mark class=\"m-accion\">podrá hacerse</mark> en una fase posterior mediante un Pliego de cargos, que <mark class=\"m-accion\">deberá notificarse</mark> a los interesados<div class=\"vis-sub\"></div></div></div></div></div>"}],"a-100":[{"t":"Medios de ejecución forzosa (arts. 100 a 104 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Medios de ejecución forzosa (arts. 100 a 104 · cuadro del temario)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Ejecución forzosa</mark>: respetando el principio de <mark class=\"m-resp\">proporcionalidad</mark>; si hay varios medios admisibles <mark class=\"m-accion\">se elegirá</mark> el <u class=\"m-clave\">menos restrictivo</u> de la libertad individual; si hay que entrar en el domicilio: consentimiento del titular o autorización judicial</div><div class=\"vis-ramas\"><div class=\"vis-rama\">Apremio sobre el patrimonio (art. 101)<div class=\"vis-sub\"><span>Cuando hubiera de satisfacerse cantidad líquida</span><span><mark class=\"m-accion\">No podrá imponerse</mark> una obligación pecuniaria no establecida con arreglo a una norma de rango legal</span></div></div><div class=\"vis-rama\">Ejecución subsidiaria (art. 102)<div class=\"vis-sub\"><span>Actos que no sean personalísimos: los realiza la Administración, por sí o a través de las personas que determine, a costa del obligado</span><span>Importe de gastos, daños y perjuicios: se exige conforme al apremio; puede liquidarse provisionalmente y antes de la ejecución</span></div></div><div class=\"vis-rama\">Multa coercitiva (art. 103)<div class=\"vis-sub\"><span>Actos personalísimos en que no proceda la compulsión directa, o en que la Administración no la estime conveniente, o cuya ejecución pueda encargarse a otra persona</span><span>Es independiente de las sanciones y compatible con ellas</span></div></div><div class=\"vis-rama\">Compulsión sobre las personas (art. 104)<div class=\"vis-sub\"><span>Actos que impongan una obligación personalísima de no hacer o soportar, cuando la ley lo autorice y con respeto a la dignidad y derechos de la Constitución</span><span>Si son obligaciones personalísimas de hacer y no se realizan: el obligado <mark class=\"m-accion\">resarcirá</mark> los daños y perjuicios</span></div></div></div></div></div>"}],"a-111":[{"t":"Competencia para la revisión de oficio de disposiciones y actos nulos y anulables en la AGE (art. 111 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Competencia para la revisión de oficio de disposiciones y actos nulos y anulables en la AGE (art. 111 · cuadro del temario)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Ámbito estatal</mark>: competentes para la revisión de oficio</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">Consejo de Ministros</mark><div class=\"vis-sub\"><span>Sus propios actos y disposiciones</span><span>Los actos y disposiciones dictados por los <mark class=\"m-autoridad\">Ministros</mark></span></div></div><div class=\"vis-rama\">Administración General del <mark class=\"m-autoridad\">Estado</mark><div class=\"vis-sub\"><span><mark class=\"m-autoridad\">Ministros:</mark> actos y disposiciones de los Secretarios de <mark class=\"m-autoridad\">Estado</mark> y de los dictados por <mark class=\"m-autoridad\">órganos</mark> directivos de su Departamento no dependientes de una <mark class=\"m-autoridad\">Secretaría de Estado</mark></span><span>Secretarios de <mark class=\"m-autoridad\">Estado:</mark> actos y disposiciones dictados por <mark class=\"m-autoridad\">órganos</mark> directivos de ellos dependientes</span></div></div><div class=\"vis-rama\">Organismos públicos y entidades de derecho público vinculados o dependientes de la AGE<div class=\"vis-sub\"><span>Los <mark class=\"m-autoridad\">órganos</mark> a los que estén adscritos: actos y disposiciones dictados por el máximo <mark class=\"m-autoridad\">órgano</mark> rector de éstos</span><span>Los máximos <mark class=\"m-autoridad\">órganos</mark> rectores: actos y disposiciones dictados por los <mark class=\"m-autoridad\">órganos</mark> de ellos dependientes</span></div></div></div></div></div>"}],"a-121":[{"t":"Recurso de alzada (arts. 121 y 122 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Recurso de alzada (arts. 121 y 122 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Objeto</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Resoluciones y actos de trámite que determinen la imposibilidad de continuar el procedimiento, produzcan indefensión o perjuicio irreparable a derechos e intereses legítimos, <u class=\"m-clave\">siempre que</u> no pongan fin a la vía administrativa.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\"><mark class=\"m-autoridad\">Órgano</mark> ante el que ha de recurrirse</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Ante el <mark class=\"m-destacable\">superior jerárquico</mark> del que dictó el acto.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Plazo</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">1 mes</span><div class=\"vt-t\">si el acto fuera expreso.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Si no fuera expreso: para el solicitante y otros posibles interesados, a partir del <mark class=\"m-plazo\">día siguiente</mark> a aquel en que se produzcan los efectos del silencio administrativo (no tiene tope máximo de un mes). Transcurridos dichos plazos sin recurso, la resolución <mark class=\"m-accion\">será</mark> <mark class=\"m-destacable\">firme</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Motivos</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Nulidad o anulabilidad. Los vicios y defectos que hagan anulable el acto <u class=\"m-clave\">no</u> <mark class=\"m-accion\">podrán</mark> ser alegados por los causantes de los mismos.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Interposición</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">10 días</span><div class=\"vt-t\">Si se interpone ante el <mark class=\"m-autoridad\">órgano</mark> que dictó el acto, éste debe remitirlo al competente para resolver con su informe y una copia completa y ordenada del expediente.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Desestimación por silencio</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">3 meses</span><div class=\"vt-t\">Plazo máximo para dictar y notificar la resolución; transcurrido sin resolución, desestimado (salvo doble silencio administrativo, que tiene efectos estimatorios).</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Contra la resolución de un recurso de alzada <u class=\"m-clave\">no</u> <mark class=\"m-accion\">cabrá</mark> ningún otro recurso administrativo, <u class=\"m-clave\">salvo</u> el recurso extraordinario de revisión.</div></div></div></div></div></div>"}],"a-123":[{"t":"Recurso potestativo de reposición (arts. 123 y 124 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Recurso potestativo de reposición (arts. 123 y 124 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Objeto</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Actos administrativos que pongan fin a la vía administrativa, <u class=\"m-clave\">excepto</u> contra los que resuelvan un recurso de alzada.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\"><mark class=\"m-autoridad\">Órgano</mark> ante el que ha de recurrirse</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Ante el <mark class=\"m-destacable\">mismo</mark> <mark class=\"m-autoridad\">órgano</mark> que dictó el acto que se impugna.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Es <mark class=\"m-destacable\">potestativo</mark>: puede optarse por interponerlo o impugnar directamente ante la jurisdicción contencioso-administrativa.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Si se hace uso de él, <u class=\"m-clave\">no</u> <mark class=\"m-accion\">podrá interponerse</mark> recurso contencioso-administrativo hasta que sea resuelto expresamente o se haya producido su desestimación presunta.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Plazos</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">1 mes</span><div class=\"vt-t\">si el acto fuera expreso. Transcurrido dicho plazo, únicamente <mark class=\"m-accion\">podrá interponerse</mark> recurso contencioso-administrativo (sin perjuicio del extraordinario de revisión).</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Si no fuera expreso: en cualquier momento a partir del día siguiente a aquel en que se produzca el acto presunto.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">1 mes</span><div class=\"vt-t\">Plazo máximo para dictar y notificar la resolución.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Contra la resolución de un recurso de reposición <u class=\"m-clave\">no</u> <mark class=\"m-accion\">podrá interponerse</mark> de nuevo dicho recurso.</div></div></div></div></div></div>"}],"a-126":[{"t":"Recurso extraordinario de revisión (arts. 125 y 126 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Recurso extraordinario de revisión (arts. 125 y 126 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Objeto</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Contra los <mark class=\"m-destacable\">actos firmes</mark> en vía administrativa.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\"><mark class=\"m-autoridad\">Órgano</mark> ante el que ha de interponerse</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Ante el <mark class=\"m-autoridad\">órgano</mark> administrativo que los dictó, que también <mark class=\"m-accion\">será</mark> el competente para su resolución.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Circunstancias que deben concurrir</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">a) Error de hecho que resulte de los propios documentos incorporados al expediente.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">b) Aparezcan documentos de valor esencial para la resolución, posteriores, que evidencien el error de la resolución recurrida.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">c) Haya influido esencialmente en la resolución documentos o testimonios declarados falsos por sentencia judicial firme.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">d) La resolución se hubiese dictado como consecuencia de prevaricación, cohecho, violencia, maquinación fraudulenta u otra conducta punible, declarada por sentencia judicial firme.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Plazos de interposición</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">4 años</span><div class=\"vt-t\">Causa de la letra a (error de hecho): desde la fecha de la notificación de la resolución impugnada.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">3 meses</span><div class=\"vt-t\">Resto de casos: a contar desde el conocimiento de los documentos o desde que la sentencia judicial quedó firme.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Inadmisión</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">El <mark class=\"m-autoridad\">órgano</mark> competente <mark class=\"m-accion\">podrá acordar</mark> motivadamente la inadmisión a trámite, sin necesidad de recabar dictamen del <mark class=\"m-autoridad\">Consejo de Estado u órgano</mark> consultivo, cuando: no se funde en alguna de las causas previstas, o se hubiesen desestimado en cuanto al fondo otros recursos sustancialmente iguales.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Resolución y silencio</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p c\">3 meses</span><div class=\"vt-t\">Plazo para la instrucción, resolución y notificación; transcurrido sin haberse dictado y notificado resolución, <mark class=\"m-accion\">se entenderá</mark> desestimado, quedando expedita la vía contencioso-administrativa.</div></div></div></div></div></div>"}],"d-13":[{"t":"Suplencia (art. 13 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Suplencia (art. 13 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Concepto</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">En la forma que disponga cada Administración Pública, los titulares de los <mark class=\"m-autoridad\">órganos</mark> administrativos <mark class=\"m-accion\">podrán</mark> ser <mark class=\"m-destacable\">suplidos temporalmente</mark>.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><u class=\"m-clave\">No</u> <mark class=\"m-accion\">implicará</mark> alteración de la competencia; para su validez <u class=\"m-clave\">no</u> <mark class=\"m-accion\">será</mark> <u class=\"m-clave\">necesaria</u> su publicación.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Si no se designa suplente, la competencia <mark class=\"m-accion\">se ejercerá</mark> por quien designe el <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-destacable\">administrativo inmediato superior</mark> de quien dependa.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Supuestos</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-plazo\">Vacante, ausencia, enfermedad</mark>, así como en los casos en que haya sido declarada su <mark class=\"m-plazo\">abstención o recusación</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Designación (en el ámbito de la AGE)</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">En los reales decretos de estructura orgánica básica de los Departamentos Ministeriales o en los estatutos de sus Organismos públicos y Entidades vinculados o dependientes.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por el <mark class=\"m-autoridad\">órgano</mark> competente para el nombramiento del titular, bien en el propio acto de nombramiento, bien en otro posterior cuando se produzca el supuesto que dé lugar a la suplencia.</div></div></div></div></div></div>"}],"b-19":[{"t":"Funciones del Secretario del órgano colegiado (tras el art. 19 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Funciones del Secretario del órgano colegiado (tras el art. 19 · cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">Corresponde</span>Asistir a las reuniones con voz pero <u class=\"m-clave\">sin voto</u> (con voz y voto si la <mark class=\"m-autoridad\">Secretaría</mark> la ostenta un miembro del mismo) · efectuar la convocatoria de las sesiones por orden del <mark class=\"m-autoridad\">Presidente,</mark> así como las citaciones a los miembros</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Además</span>Recibir los actos de comunicación de los miembros con el <mark class=\"m-autoridad\">órgano</mark> · preparar el despacho de los asuntos, redactar y autorizar las actas · <mark class=\"m-resp\">expedir certificaciones</mark> de las consultas, dictámenes y acuerdos aprobados · cuantas otras funciones sean inherentes a su condición</div></div></div>"}],"b-21":[{"t":"Órganos colegiados de la Administración General del Estado (art. 21 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Órganos colegiados de la Administración General del Estado (art. 21 · cuadro del temario)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Interministeriales</h5><ul><li>Sus miembros proceden de <mark class=\"m-destacable\">diferentes</mark> <mark class=\"m-autoridad\">Ministerios</mark>.</li></ul></div><div class=\"vis-col\"><h5>Ministeriales</h5><ul><li>Sus componentes proceden de los <mark class=\"m-autoridad\">órganos</mark> de <mark class=\"m-destacable\">un solo</mark> <mark class=\"m-autoridad\">Ministerio</mark>.</li></ul></div><div class=\"vis-col\"><h5>Composición</h5><ul><li><mark class=\"m-accion\">Podrá haber</mark> representantes de otras Administraciones Públicas cuando: éstas lo acepten <mark class=\"m-plazo\">voluntariamente</mark>, un convenio así lo establezca o una norma aplicable lo determine.</li><li><mark class=\"m-accion\">Podrán participar</mark> organizaciones representativas de intereses sociales y otros miembros designados por su experiencia o conocimientos.</li></ul></div></div></div>"}],"b-24":[{"t":"Abstención y recusación (arts. 23 y 24 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Abstención y recusación (arts. 23 y 24 · cuadro del temario)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>ABSTENCIÓN (art. 23): motivos</h5><ul><li>Tener <mark class=\"m-destacable\">interés personal</mark> en el asunto o en otro en cuya resolución pudiera influir; ser administrador de sociedad o entidad interesada, o tener cuestión litigiosa pendiente con algún interesado.</li><li>Vínculo matrimonial o situación de hecho asimilable y parentesco de consanguinidad dentro del <mark class=\"m-plazo\">cuarto grado</mark> o de afinidad dentro del <mark class=\"m-plazo\">segundo</mark> con cualquiera de los interesados, administradores, asesores, representantes legales o mandatarios.</li><li><mark class=\"m-destacable\">Amistad íntima</mark> o enemistad manifiesta con alguna de las personas mencionadas.</li><li>Haber intervenido como <mark class=\"m-destacable\">perito o testigo</mark> en el procedimiento.</li><li>Tener <mark class=\"m-destacable\">relación de servicio</mark> con persona interesada directamente en el asunto, o haberle prestado en los <mark class=\"m-plazo\">dos últimos años</mark> servicios profesionales de cualquier tipo.</li></ul></div><div class=\"vis-col\"><h5>RECUSACIÓN (art. 24)</h5><ul><li><mark class=\"m-accion\">Podrá promoverse</mark> en cualquier momento de la tramitación del procedimiento.</li><li><mark class=\"m-accion\">Se planteará</mark> <mark class=\"m-destacable\">por escrito</mark> expresando la causa.</li><li>En el <mark class=\"m-plazo\">día siguiente</mark> el recusado <mark class=\"m-accion\">manifestará</mark> a su inmediato superior si se da o no la causa; si se da, <mark class=\"m-accion\">acordará</mark> su sustitución acto seguido.</li><li>Si el recusado niega la causa, el superior <mark class=\"m-accion\">resolverá</mark> en el plazo de <mark class=\"m-plazo\">3 días</mark>, previos los informes y comprobaciones oportunas.</li><li>Contra las resoluciones adoptadas <u class=\"m-clave\">no</u> <mark class=\"m-accion\">cabrá</mark> <u class=\"m-clave\">recurso</u>, sin perjuicio de alegar la recusación al interponer el recurso contra el acto que ponga fin al procedimiento.</li></ul></div></div></div>"}],"d-55":[{"t":"La Administración General del Estado comprende (art. 55 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>La Administración General del Estado comprende (art. 55 · cuadro del temario)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Administración General del</mark> <mark class=\"m-autoridad\">Estado</mark>: organización por principios de <mark class=\"m-plazo\">división funcional</mark> en Departamentos ministeriales y de <mark class=\"m-plazo\">gestión territorial</mark> en Delegaciones del <mark class=\"m-autoridad\">Gobierno</mark> (salvo excepciones)</div><div class=\"vis-ramas\"><div class=\"vis-rama\">Organización central: integra los <mark class=\"m-autoridad\">Ministerios</mark> y los servicios comunes (funcional → <mark class=\"m-autoridad\">Ministerios)</mark></div><div class=\"vis-rama\">Organización territorial: Delegaciones y Subdelegaciones del <mark class=\"m-autoridad\">Gobierno</mark> (territorial → Delegaciones en las CCAA)</div><div class=\"vis-rama\">Administración General del <mark class=\"m-autoridad\">Estado</mark> en el exterior: Misiones diplomáticas, etc.</div></div></div></div>"},{"t":"Organización central de la AGE: órganos superiores y directivos (art. 55.3 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Organización central de la AGE: órganos superiores y directivos (art. 55.3 · cuadro del temario)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Organización central</mark>: son <mark class=\"m-autoridad\">órganos</mark> superiores y <mark class=\"m-autoridad\">órganos</mark> directivos</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">Órganos</mark> superiores<div class=\"vis-sub\"><span>Los <mark class=\"m-autoridad\">Ministros</mark></span><span>Los Secretarios de <mark class=\"m-autoridad\">Estado</mark></span></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Órganos</mark> directivos<div class=\"vis-sub\"><span>Los Subsecretarios y Secretarios generales</span><span>Los Secretarios generales técnicos y Directores generales</span><span>Los Subdirectores generales</span></div></div><div class=\"vis-rama\">Organización territorial (55.4): son <mark class=\"m-autoridad\">órganos</mark> directivos los <mark class=\"m-autoridad\">Delegados del Gobierno</mark> en las CCAA (rango de Subsecretario) y los Subdelegados del <mark class=\"m-autoridad\">Gobierno</mark> en las provincias (nivel de Subdirector general)<div class=\"vis-sub\"></div></div><div class=\"vis-rama\">En el exterior (55.5): <mark class=\"m-autoridad\">órganos</mark> directivos los embajadores y representantes permanentes ante Organizaciones internacionales<div class=\"vis-sub\"></div></div><div class=\"vis-rama\">Alto cargo (55.6): los <mark class=\"m-autoridad\">órganos</mark> superiores y directivos, <u class=\"m-clave\">excepto</u> los Subdirectores generales<div class=\"vis-sub\"></div></div></div></div></div>"}],"a-41":[{"t":"Condiciones generales para la práctica de las notificaciones (art. 41 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Condiciones generales para la práctica de las notificaciones (art. 41 · cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Concepto</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Práctica</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por <mark class=\"m-destacable\">medios electrónicos</mark>: preferentemente y, <u class=\"m-clave\">en todo caso</u>, cuando el interesado resulte obligado a recibirlas por esta vía.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><u class=\"m-clave\">No obstante</u>, <mark class=\"m-accion\">podrán practicarse</mark> por medios <u class=\"m-clave\">no</u> electrónicos cuando: la notificación se realice por comparecencia espontánea del interesado o su representante en las oficinas de asistencia en materia de registro y solicite la comunicación o notificación personal en ese momento · para asegurar la eficacia de la actuación administrativa resulte necesario practicarla por entrega directa de un empleado público de la Administración notificante.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Validez</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><u class=\"m-clave\">Siempre que</u> permitan tener constancia de: su envío o puesta a disposición · recepción o acceso por el interesado o su representante · sus fechas y horas · contenido íntegro · identidad fidedigna del remitente y destinatario.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et c\">Prohibiciones</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><u class=\"m-clave\">En ningún caso</u> <mark class=\"m-accion\">se efectuarán</mark> por medios electrónicos: cuando el acto a notificar vaya acompañado de elementos que <u class=\"m-clave\">no</u> sean susceptibles de conversión en formato electrónico · las que contengan medios de pago a favor de los obligados (por ejemplo, cheques).</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">Según procedimiento</div><div class=\"vt-hijos\"><div class=\"vt-nodo\"><div class=\"vt-et v\">Iniciado a solicitud del interesado</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Se practica en el medio señalado por el interesado · <mark class=\"m-accion\">será</mark> electrónica cuando resulte obligado · si <u class=\"m-clave\">no</u> fuera posible conforme a lo señalado, <mark class=\"m-accion\">se practicará</mark> en cualquier lugar adecuado y por cualquier medio que permita tener constancia de la recepción, fecha, identidad y contenido.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">Iniciado de oficio</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Las Administraciones <mark class=\"m-accion\">podrán recabar</mark>, mediante consulta a las bases de datos del <mark class=\"m-destacable\">Instituto Nacional de Estadística</mark>, los datos sobre el domicilio del interesado recogidos en el Padrón Municipal, remitidos por las Entidades Locales.</div></div></div></div></div></div></div></div>"}],"b-60":[{"t":"Ordenación jerárquica de los órganos ministeriales (art. 60 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Ordenación jerárquica de los órganos ministeriales (art. 60 · cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">Ministros</span><mark class=\"m-destacable\">Jefes superiores del Departamento</mark> y superiores jerárquicos <mark class=\"m-resp\">directos</mark> de los Secretarios de <mark class=\"m-autoridad\">Estado</mark> y Subsecretarios</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Órganos directivos</span>Dependen de alguno de los anteriores y se ordenan jerárquicamente entre sí: <mark class=\"m-plazo\">Subsecretario → Director general → Subdirector general</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">Categorías</span>Los <mark class=\"m-destacable\">Secretarios generales</mark> tienen categoría de <mark class=\"m-resp\">Subsecretario</mark> · los <mark class=\"m-destacable\">Secretarios generales técnicos</mark> tienen categoría de <mark class=\"m-resp\">Director general</mark></div></div></div>"}],"t-32":[{"t":"Prescripción de infracciones y sanciones (art. 32 Ley 19/2013 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Prescripción de infracciones y sanciones (art. 32 Ley 19/2013 · cuadro del temario)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Muy graves</h5><ul><li>Infracciones: <mark class=\"m-plazo\">5 años</mark></li><li>Sanciones: <mark class=\"m-plazo\">5 años</mark></li></ul></div><div class=\"vis-col\"><h5>Graves</h5><ul><li>Infracciones: <mark class=\"m-plazo\">3 años</mark></li><li>Sanciones: <mark class=\"m-plazo\">3 años</mark></li></ul></div><div class=\"vis-col\"><h5>Leves</h5><ul><li>Infracciones: <mark class=\"m-plazo\">1 año</mark></li><li>Sanciones: <mark class=\"m-plazo\">1 año</mark></li></ul></div></div></div>"}],"d-31":[{"t":"Competencia para imponer sanciones (art. 31.4 Ley 19/2013 · cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Competencia para imponer sanciones (art. 31.4 Ley 19/2013 · cuadro del temario)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Competencia</mark> para la imposición de sanciones</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-autoridad\">Consejo de Ministros:</mark> cuando el alto cargo tenga la condición de miembro del <mark class=\"m-autoridad\">Gobierno o Secretario de Estado</mark></div><div class=\"vis-rama\">Ministro de Hacienda y Administraciones Públicas: cuando el responsable sea un alto cargo de la Administración General del <mark class=\"m-autoridad\">Estado</mark></div><div class=\"vis-rama\">Altos cargos de las CCAA y Entidades Locales: los <mark class=\"m-autoridad\">órganos</mark> que tengan atribuidas estas funciones en aplicación del régimen disciplinario propio, en su caso el <mark class=\"m-autoridad\">Consejo de Gobierno</mark> de la Comunidad Autónoma o el Pleno de la Junta de <mark class=\"m-autoridad\">Gobierno</mark> de la Entidad Local</div></div></div></div>"}]};